use actix_web::{App, HttpServer, web};
use std::sync::Arc;
use std::time::Duration;
use tracing_actix_web::TracingLogger;

mod config;
mod db;
mod error;
mod handlers;
mod middleware;
mod models;
mod services;
mod utils;

use config::AppConfig;
use middleware::api_key_auth::ApiKeyAuth;
use middleware::rate_limiter::RateLimiter;
use services::api_key_state_cache::ApiKeyStateCache;
use services::custom_holiday_cache::CustomHolidayCache;
use services::holiday_cache::HolidayCache;
use services::usage_tracker::UsageBatcher;

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    dotenvy::dotenv().ok();

    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    let config = AppConfig::from_env();
    let pool = db::init_pool(&config.database_url).await;

    // Run migrations
    run_migrations(&pool).await;

    let host = config.host.clone();
    let port = config.port;
    let holiday_cache = web::Data::new(HolidayCache::new());
    let custom_holiday_cache = web::Data::new(CustomHolidayCache::new(Duration::from_secs(60)));
    let api_key_state_cache = web::Data::new(Arc::new(ApiKeyStateCache::new(Duration::from_secs(
        config.api_key_state_cache_ttl_seconds,
    ))));
    let usage_batcher = Arc::new(UsageBatcher::new());
    Arc::clone(&usage_batcher).start_flush_worker(pool.clone(), Duration::from_secs(30));
    let usage_batcher = web::Data::new(usage_batcher);

    tracing::info!("Starting server on {host}:{port}");

    HttpServer::new(move || {
        App::new()
            .wrap(TracingLogger::default())
            .wrap(RateLimiter::new(1000))
            .wrap(ApiKeyAuth)
            .app_data(web::Data::new(pool.clone()))
            .app_data(web::Data::new(config.clone()))
            .app_data(holiday_cache.clone())
            .app_data(custom_holiday_cache.clone())
            .app_data(api_key_state_cache.clone())
            .app_data(usage_batcher.clone())
            .service(handlers::health::health_check)
            .service(handlers::holiday::get_holidays)
            .service(handlers::admin::sync_holidays)
            .service(handlers::admin::invalidate_api_key_cache)
            .service(handlers::business_day::get_business_days_count)
            .service(handlers::business_day::get_business_days_add)
            .service(handlers::business_day::get_business_days_subtract)
            .service(handlers::business_day::get_business_days_check)
    })
    .bind(format!("{host}:{port}"))?
    .run()
    .await
}

async fn run_migrations(pool: &sqlx::PgPool) {
    let migrations = [
        include_str!("../migrations/001_create_api_keys.sql"),
        include_str!("../migrations/002_create_public_holidays.sql"),
        include_str!("../migrations/003_create_custom_holidays.sql"),
        include_str!("../migrations/004_create_api_usage.sql"),
        include_str!("../migrations/005_add_composite_index.sql"),
        include_str!("../migrations/006_add_api_key_token_version.sql"),
        include_str!("../migrations/007_drop_token_version.sql"),
        include_str!("../migrations/008_create_api_usage_daily.sql"),
    ];

    let batch = migrations.join(";\n");
    match sqlx::raw_sql(&batch).execute(pool).await {
        Ok(_) => tracing::info!("All {} migrations applied successfully", migrations.len()),
        Err(e) => tracing::warn!("Migration batch (may already exist): {e}"),
    }
}

