use chrono::NaiveDate;
use serde::Serialize;
use sqlx::FromRow;
use uuid::Uuid;

#[derive(Debug, Clone, FromRow)]
pub struct PublicHoliday {
    pub id: i32,
    pub name: String,
    pub date: NaiveDate,
    pub year: i32,
    pub month: i32,
    pub day: i32,
    pub day_of_week: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, FromRow)]
pub struct CustomHoliday {
    pub id: Uuid,
    pub user_id: Uuid,
    pub name: String,
    pub date: NaiveDate,
    pub year: i32,
    pub month: i32,
    pub day: i32,
    pub day_of_week: String,
}

#[derive(Debug, Serialize)]
pub struct HolidayResponse {
    pub id: String,
    pub name: String,
    pub date: String,
    pub year: i32,
    pub month: i32,
    pub day: i32,
    pub day_of_week: String,
    #[serde(rename = "type")]
    pub holiday_type: String,
}

impl From<PublicHoliday> for HolidayResponse {
    fn from(h: PublicHoliday) -> Self {
        Self {
            id: h.id.to_string(),
            name: h.name,
            date: h.date.to_string(),
            year: h.year,
            month: h.month,
            day: h.day,
            day_of_week: h.day_of_week,
            holiday_type: "public".to_string(),
        }
    }
}

impl From<CustomHoliday> for HolidayResponse {
    fn from(h: CustomHoliday) -> Self {
        Self {
            id: h.id.to_string(),
            name: h.name,
            date: h.date.to_string(),
            year: h.year,
            month: h.month,
            day: h.day,
            day_of_week: h.day_of_week,
            holiday_type: "custom".to_string(),
        }
    }
}

