use std::sync::Arc;

use actix_web::{HttpMessage, HttpRequest, HttpResponse, get, web};
use chrono::NaiveDate;
use serde::Deserialize;
use sqlx::PgPool;

use crate::error::AppError;
use crate::middleware::api_key_auth::AuthContext;
use crate::models::holiday::HolidayResponse;
use crate::services::custom_holiday_cache::CustomHolidayCache;
use crate::services::holiday_cache::HolidayCache;
use crate::services::usage_tracker::UsageBatcher;
use crate::utils::response::ApiResponse;

#[derive(Deserialize)]
pub struct HolidayQuery {
    pub year: Option<i32>,
}

#[get("/v1/holidays")]
pub async fn get_holidays(
    req: HttpRequest,
    pool: web::Data<PgPool>,
    holiday_cache: web::Data<HolidayCache>,
    custom_holiday_cache: web::Data<CustomHolidayCache>,
    usage_batcher: web::Data<Arc<UsageBatcher>>,
    query: web::Query<HolidayQuery>,
) -> Result<HttpResponse, AppError> {
    let t0 = std::time::Instant::now();

    let auth = {
        let extensions = req.extensions();
        extensions
            .get::<AuthContext>()
            .ok_or_else(|| AppError::Unauthorized("Missing auth context".to_string()))?
            .clone()
    };
    let user_id = auth.user_id;
    let api_key_id = auth.api_key_id;
    tracing::info!(us = t0.elapsed().as_micros(), "PERF auth_extract");

    let (from_date, to_date) = resolve_date_range(&query)?;

    let public_holidays = holiday_cache
        .get_holidays(pool.get_ref(), from_date, to_date)
        .await?;
    tracing::info!(us = t0.elapsed().as_micros(), "PERF holiday_cache");

    // Pro 플랜만 커스텀 공휴일 포함
    let custom_holidays = if auth.has_pro {
        custom_holiday_cache
            .get_holidays(pool.get_ref(), user_id, from_date, to_date)
            .await?
    } else {
        vec![]
    };
    tracing::info!(us = t0.elapsed().as_micros(), "PERF custom_holiday_cache");

    usage_batcher.increment(api_key_id).await;
    tracing::info!(us = t0.elapsed().as_micros(), "PERF usage_increment");

    let mut holidays: Vec<HolidayResponse> =
        Vec::with_capacity(public_holidays.len() + custom_holidays.len());
    holidays.extend(public_holidays.into_iter().map(HolidayResponse::from));
    holidays.extend(custom_holidays.into_iter().map(HolidayResponse::from));
    holidays.sort_by(|a, b| a.date.cmp(&b.date));

    let resp = HttpResponse::Ok().json(ApiResponse::ok(holidays));
    tracing::info!(us = t0.elapsed().as_micros(), "PERF handler_total");
    Ok(resp)
}

fn resolve_date_range(query: &HolidayQuery) -> Result<(NaiveDate, Option<NaiveDate>), AppError> {
    if let Some(year) = query.year {
        let from_date = NaiveDate::from_ymd_opt(year, 1, 1)
            .ok_or_else(|| AppError::BadRequest("Invalid year".to_string()))?;
        let to_date = NaiveDate::from_ymd_opt(year, 12, 31)
            .ok_or_else(|| AppError::BadRequest("Invalid year".to_string()))?;
        Ok((from_date, Some(to_date)))
    } else {
        let today = chrono::Utc::now().naive_utc().date();
        Ok((today, None))
    }
}

