use actix_web::dev::{Service, ServiceRequest, ServiceResponse, Transform, forward_ready};
use actix_web::{Error, HttpMessage, web};
use futures::future::{LocalBoxFuture, Ready, ok};
use sqlx::PgPool;
use std::rc::Rc;
use std::sync::Arc;

use crate::error::AppError;
use crate::services::api_key_state_cache::ApiKeyStateCache;

/// 월간 API 호출 한도
const FREE_MONTHLY_QUOTA: i64 = 100;
const PRO_MONTHLY_QUOTA: i64 = 5000;

#[derive(Clone)]
pub struct AuthContext {
    pub api_key_id: uuid::Uuid,
    pub user_id: uuid::Uuid,
    pub has_pro: bool,
}

pub struct ApiKeyAuth;

impl<S, B> Transform<S, ServiceRequest> for ApiKeyAuth
where
    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
    B: 'static,
{
    type Response = ServiceResponse<B>;
    type Error = Error;
    type Transform = ApiKeyAuthMiddleware<S>;
    type InitError = ();
    type Future = Ready<Result<Self::Transform, Self::InitError>>;

    fn new_transform(&self, service: S) -> Self::Future {
        ok(ApiKeyAuthMiddleware {
            service: Rc::new(service),
        })
    }
}

pub struct ApiKeyAuthMiddleware<S> {
    service: Rc<S>,
}

impl<S, B> Service<ServiceRequest> for ApiKeyAuthMiddleware<S>
where
    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
    B: 'static,
{
    type Response = ServiceResponse<B>;
    type Error = Error;
    type Future = LocalBoxFuture<'static, Result<Self::Response, Self::Error>>;

    forward_ready!(service);

    fn call(&self, req: ServiceRequest) -> Self::Future {
        let service = Rc::clone(&self.service);

        Box::pin(async move {
            // Skip auth for health and admin endpoints
            if req.path() == "/v1/health" || req.path().starts_with("/v1/admin/") {
                return service.call(req).await;
            }

            let t0 = std::time::Instant::now();

            let api_key = req
                .headers()
                .get("x-api-key")
                .and_then(|v| v.to_str().ok())
                .map(str::trim)
                .filter(|k| !k.is_empty())
                .ok_or_else(|| AppError::Unauthorized("Missing x-api-key header".to_string()))?;

            let pool = req
                .app_data::<web::Data<PgPool>>()
                .ok_or_else(|| AppError::Internal("Missing DB pool".to_string()))?;
            let cache = req
                .app_data::<web::Data<Arc<ApiKeyStateCache>>>()
                .ok_or_else(|| AppError::Internal("Missing API key state cache".to_string()))?;

            let state = cache.get_or_load(pool.get_ref(), api_key).await?;
            tracing::info!(us = t0.elapsed().as_micros(), "PERF api_key_auth");

            if !state.is_active {
                return Err(AppError::Unauthorized("API key is deactivated".to_string()).into());
            }

            // 월간 쿼타 체크
            let quota = if state.has_pro {
                PRO_MONTHLY_QUOTA
            } else {
                FREE_MONTHLY_QUOTA
            };
            if state.monthly_usage >= quota {
                return Err(AppError::QuotaExceeded {
                    used: state.monthly_usage,
                    limit: quota,
                }
                .into());
            }

            req.extensions_mut().insert(AuthContext {
                api_key_id: state.api_key_id,
                user_id: state.user_id,
                has_pro: state.has_pro,
            });

            service.call(req).await
        })
    }
}

